using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
namespace Tikal.Tests.Editor {
public static class PlazaKeynesDeliveryAudit {
 [Serializable]public class Contact{public string name;public float baseY,groundY,gap;public bool intendedBurial,reviewRequired;}
 [Serializable]public class Result{public bool passed,sceneUnchanged;public string[] dependencies,newDependencies,missingFiles;public Contact[] contacts;public int contactReviews;}
 static string Hash(string p){using(var h=System.Security.Cryptography.SHA256.Create())using(var f=File.OpenRead(p))return BitConverter.ToString(h.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
 public static void Run(){try{string scene=PlazaKeynesAuthoring.ScenePath,before=Hash(scene);EditorSceneManager.OpenScene(scene);var env=GameObject.Find("ENV_Level02_PlazaKeynes");var contacts=new List<Contact>();foreach(var g in env.GetComponentsInChildren<LODGroup>()){if(!new[]{"Ruins_","Columns_","Rocks_","SmallVegetation_","MidgroundTrees_","BackgroundTrees_","BackgroundUnderstorey_"}.Any(p=>g.name.StartsWith(p)))continue;if(g.GetComponentsInParent<Transform>().Any(t=>t.name.StartsWith("RuinedCourt_")))continue;var bounds=PlazaKeynesAuthoring.BoundsOf(g.gameObject);float ground=PlazaKeynesAuthoring.Height(g.transform.position.x,g.transform.position.z);float gap=bounds.min.y-ground;contacts.Add(new Contact{name=g.name,baseY=bounds.min.y,groundY=ground,gap=gap,intendedBurial=gap<0,reviewRequired=gap>.25f});}var deps=AssetDatabase.GetDependencies(scene,true);var missing=deps.Where(p=>p.StartsWith("Assets/")&&!File.Exists(p)).ToArray();var newDeps=deps.Where(p=>p.StartsWith("Assets/")&&!File.Exists("D:/ARCHIVOS/TREVIX/Proyectos/Videojuegos/Tikal_ElPortal/My project/"+p)).ToArray();var result=new Result{passed=!missing.Any()&&contacts.All(c=>!c.reviewRequired),sceneUnchanged=Hash(scene)==before,dependencies=deps,newDependencies=newDeps,missingFiles=missing,contacts=contacts.ToArray(),contactReviews=contacts.Count(c=>c.reviewRequired)};File.WriteAllText(PlazaKeynesAuthoring.Evidence+"/Delivery_Audit.json",JsonUtility.ToJson(result,true));EditorApplication.Exit(result.passed?0:5);}catch(Exception e){File.WriteAllText(PlazaKeynesAuthoring.Evidence+"/Delivery_Audit_Error.txt",e.ToString());EditorApplication.Exit(6);}}
}
}
